/**
 * Shows which deployed Squatch build is actually being served, in Pacific time.
 * The manifest is generated by Cloudflare Pages at build time. We never fetch
 * private GitHub APIs from a visitor's browser or substitute the user's clock.
 */
const PACIFIC='America/Los_Angeles';
export function pacificTimestamp(iso){
 const d=new Date(iso);
 if(!Number.isFinite(d.getTime()))throw new RangeError('Invalid deploy timestamp');
 return new Intl.DateTimeFormat('en-US',{
  timeZone:PACIFIC,year:'numeric',month:'short',day:'numeric',
  hour:'numeric',minute:'2-digit',timeZoneName:'short'
 }).format(d);
}

export function validDeploymentManifest(m){
 return m&&m.schemaVersion===1&&m.source==='cloudflare-pages-build'&&
  /^[0-9a-f]{40}$/.test(m.commit)&&Number.isFinite(Date.parse(m.deploymentBuildAt))&&
  typeof m.branch==='string';
}

export async function updateDeploymentBanner({
 target,note,fetcher=fetch
}={}){
 if(!target)return false;
 try{
  const response=await fetcher('./deployment.json',{cache:'no-store'});
  if(!response.ok)return false;
  const data=await response.json();
  if(!validDeploymentManifest(data))return false;
  const isProduction=data.branch==='main';
  const label=isProduction?'DEPLOYED':'PREVIEW BUILD';
  target.textContent=pacificTimestamp(data.deploymentBuildAt);
  target.dateTime=data.deploymentBuildAt;
  target.title='Cloudflare Pages build timestamp (deployment follows build). Commit '+data.commit;
  if(note)note.textContent=label+' · '+data.commit.slice(0,7);
  return true;
 }catch{
  // Keep the last verified deployment timestamp displayed in HTML. Never
  // replace it with "now" or an unrelated Git commit timestamp.
  return false;
 }
}

if(typeof document!=='undefined'){
 void updateDeploymentBanner({
  target:document.querySelector('#deployment-time'),
  note:document.querySelector('#deployment-note')
 });
}
